  if (this.freeList.length < this.maxSize) {
    // Clear mutable fields so the next acquire() never inherits stale data
    // (e.g., a deleted Sign's "Welcome" text appearing on a new Villager).
    obj.text = '';
    obj.ttl  = 0;
    this.freeList.push(obj);
  }
}
```

Alternatively — and more robustly, to keep the `Pool` class generic — add a `reset` callback to the constructor and call it in `release()`, the same way the richer `ObjectPool` in `object_pool.js` uses `item.reset()`:

```js
// FIXED (generic approach)
class Pool {
  constructor(factory, maxSize, reset = null) {
    this.factory  = factory;
    this.maxSize  = maxSize;
    this.reset    = reset;   // optional (obj) => void
    this.freeList = [];
  }
  acquire() {
    return this.freeList.pop() || this.factory();
  }
  release(obj) {
    if (this.freeList.length < this.maxSize) {
      if (typeof this.reset === 'function') {
        this.reset(obj);
      }
      this.freeList.push(obj);
    }
  }
